old='{role===\'admin\'&&<label className="block text-sm">周期表达式（留空为手动）<input className={field} value={draft.schedule} onChange={e=>setDraft({...draft,schedule:e.target.value})}/><small className="text-text-muted">例如每天 10:00：0 10 * * *。也可到周期调度页使用时间设置。</small></label>}'
