s+='''
function ScheduleEditor({value,onChange}:{value:string;onChange:(value:string)=>void}){
 const daily=/^\\d+ \\d+ \\* \\* \\*$/.test(value);const [advanced,setAdvanced]=useState(!!value&&!daily);
 return <div className="space-y-3"><label className="block text-sm">运行方式<select className={field} value={!value?'manual':advanced?'advanced':'daily'} onChange={e=>{setAdvanced(e.target.value==='advanced');onChange(e.target.value==='manual'?'':e.target.value==='daily'?'0 10 * * *':value||'0 10 * * *')}}><option value="manual">手动运行</option><option value="daily">每天定时</option><option value="advanced">自定义周期</option></select></label>{value&&(advanced?<label className="block text-sm">自定义周期表达式<input className={field} value={value} onChange={e=>onChange(e.target.value)}/><small>保留现有复杂周期；完整周期设置也可在周期调度中修改。</small></label>:<label className="block text-sm">每天时间（北京时间）<input type="time" className={field} value={(value.split(' ')[1]||'10').padStart(2,'0')+':'+(value.split(' ')[0]||'0').padStart(2,'0')} onChange={e=>{const [h,m]=e.target.value.split(':');onChange(`${Number(m)} ${Number(h)} * * *`)}}/></label>)}</div>;
}
''';p.write_text(s)
